'use strict';
/* Ground-plane navigation shared by humans, animals and the player.
   Visible tops/crowns do not collide; trunks and object footprints do. */
function navIgnored(s,allow){return !!(allow&&allow.includes(s.tag));}
function navContains(x,y,s,pad=0){if(s.c){const rx=(s.rx||s.r)+pad,ry=(s.ry||s.r)+pad;return ((x-s.x)/rx)**2+((y-s.y)/ry)**2<1-1e-8;}return x>s.x-pad+1e-8&&x<s.x+s.w+pad-1e-8&&y>s.y-pad+1e-8&&y<s.y+s.h+pad-1e-8;}
function navPointFree(x,y,pad=4,allow=[]){return x>=20+pad&&x<=WW-20-pad&&y>=36+pad&&y<=WH-18-pad&&!SOLIDS.some(s=>!navIgnored(s,allow)&&navContains(x,y,s,pad));}
function navProjectPoint(x,y,pad=4,allow=[]){x=clamp(x,20+pad,WW-20-pad);y=clamp(y,36+pad,WH-18-pad);for(let pass=0;pass<8;pass++){let moved=false;for(const s of SOLIDS){if(navIgnored(s,allow)||!navContains(x,y,s,pad))continue;moved=true;if(s.c){const rx=(s.rx||s.r)+pad+.15,ry=(s.ry||s.r)+pad+.15;let nx=(x-s.x)/rx,ny=(y-s.y)/ry,d=Math.hypot(nx,ny);if(d<1e-8){nx=0;ny=1;d=1;}x=s.x+nx/d*rx;y=s.y+ny/d*ry;}else{const e=.15,left=s.x-pad-e,right=s.x+s.w+pad+e,top=s.y-pad-e,bottom=s.y+s.h+pad+e;const options=[[Math.abs(x-left),left,y],[Math.abs(right-x),right,y],[Math.abs(y-top),x,top],[Math.abs(bottom-y),x,bottom]];options.sort((a,b)=>a[0]-b[0]);x=options[0][1];y=options[0][2];}}if(!moved)break;}return{x,y};}
function navClear(ax,ay,bx,by,pad=4,allow=[]){
  for(const s of SOLIDS){if(navIgnored(s,allow))continue;
    if(s.c){const rx=(s.rx||s.r)+pad,ry=(s.ry||s.r)+pad,px=(ax-s.x)/rx,py=(ay-s.y)/ry,dx=(bx-ax)/rx,dy=(by-ay)/ry;const t=clamp(-(px*dx+py*dy)/(dx*dx+dy*dy||1),0,1);if((px+dx*t)**2+(py+dy*t)**2<1-1e-7)return false;}
    else{let lo=0,hi=1;const dx=bx-ax,dy=by-ay;let hit=true;for(const[p,q]of[[-dx,ax-(s.x-pad)],[dx,s.x+s.w+pad-ax],[-dy,ay-(s.y-pad)],[dy,s.y+s.h+pad-ay]]){if(Math.abs(p)<1e-9){if(q<0){hit=false;break;}}else{const r=q/p;if(p<0)lo=Math.max(lo,r);else hi=Math.min(hi,r);if(lo>hi){hit=false;break;}}}if(hit&&hi>1e-5&&lo<1-1e-5)return false;}
  }return true;
}
const NAV_CELL=12,NAV_COLS=Math.ceil(WW/NAV_CELL),NAV_ROWS=Math.ceil(WH/NAV_CELL),NAV_GRIDS=new Map();
function navGrid(pad,allow){const key=pad+':'+allow.join(',');if(!NAV_GRIDS.has(key)){const grid=new Uint8Array(NAV_COLS*NAV_ROWS);for(let y=0;y<NAV_ROWS;y++)for(let x=0;x<NAV_COLS;x++)grid[y*NAV_COLS+x]=navPointFree(x*NAV_CELL+6,y*NAV_CELL+6,pad+.35,allow)?1:0;NAV_GRIDS.set(key,grid);}return NAV_GRIDS.get(key);}
function navPath(ax,ay,bx,by,pad=4,allow=[]){if(navClear(ax,ay,bx,by,pad,allow))return[{x:bx,y:by}];const grid=navGrid(pad,allow),len=grid.length;
  function nearest(x,y){let best=-1,bd=Infinity;const cx=Math.floor(x/12),cy=Math.floor(y/12);for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){const nx=cx+dx,ny=cy+dy,id=ny*NAV_COLS+nx;if(nx<0||nx>=NAV_COLS||ny<0||ny>=NAV_ROWS||!grid[id])continue;const px=nx*12+6,py=ny*12+6,d=(px-x)**2+(py-y)**2;if(d<bd&&navClear(x,y,px,py,pad,allow)){best=id;bd=d;}}return best;}
  const start=nearest(ax,ay),end=nearest(bx,by);if(start<0||end<0)return[];const g=new Float64Array(len);g.fill(Infinity);const parent=new Int32Array(len);parent.fill(-1);const closed=new Uint8Array(len),heap=[];g[start]=0;
  const pos=id=>({x:(id%NAV_COLS)*12+6,y:Math.floor(id/NAV_COLS)*12+6});const goal=pos(end);
  function push(id,f){heap.push({id,f});let k=heap.length-1;while(k>0){const p=(k-1)>>1;if(heap[p].f<=f)break;heap[k]=heap[p];k=p;}heap[k]={id,f};}
  function pop(){const out=heap[0],last=heap.pop();if(heap.length){let k=0;while(k*2+1<heap.length){let c=k*2+1;if(c+1<heap.length&&heap[c+1].f<heap[c].f)c++;if(last.f<=heap[c].f)break;heap[k]=heap[c];k=c;}heap[k]=last;}return out.id;}
  push(start,0);let found=false;while(heap.length){const id=pop();if(closed[id])continue;closed[id]=1;if(id===end){found=true;break;}const p=pos(id),ix=id%NAV_COLS,iy=Math.floor(id/NAV_COLS);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const nx=ix+dx,ny=iy+dy,j=ny*NAV_COLS+nx;if(nx<0||nx>=NAV_COLS||ny<0||ny>=NAV_ROWS||!grid[j]||closed[j])continue;const q=pos(j);if(!navClear(p.x,p.y,q.x,q.y,pad,allow))continue;const score=g[id]+Math.hypot(dx,dy)*12;if(score<g[j]){g[j]=score;parent[j]=id;push(j,score+Math.hypot(q.x-goal.x,q.y-goal.y));}}}
  if(!found)return[];const chain=[{x:bx,y:by}];for(let id=end;id>=0;id=parent[id]){chain.push(pos(id));if(id===start)break;}chain.reverse();const smooth=[];let x=ax,y=ay,i=0;while(i<chain.length){let j=chain.length-1;while(j>i&&!navClear(x,y,chain[j].x,chain[j].y,pad,allow))j--;smooth.push(chain[j]);x=chain[j].x;y=chain[j].y;i=j+1;}return smooth;
}
function navMove(a,tx,ty,sp,dt,pad=4){const allow=a.navAllow||[],start=navProjectPoint(a.x,a.y,pad,allow),target=navProjectPoint(tx,ty,pad,allow);a.x=start.x;a.y=start.y;if(a.tx===tx&&a.ty===ty){a.tx=target.x;a.ty=target.y;}const distance=dist(a.x,a.y,target.x,target.y);if(distance<.6)return distance;
  let route=a._navRoute;if(!route||!route.length||!a._navTarget||dist(target.x,target.y,a._navTarget.x,a._navTarget.y)>8){route=a._navRoute=navPath(a.x,a.y,target.x,target.y,pad,allow);a._navTarget=target;}
  while(route.length&&dist(a.x,a.y,route[0].x,route[0].y)<.8)route.shift();const next=route[0];if(!next)return distance;const d=dist(a.x,a.y,next.x,next.y),step=Math.min(d,sp*dt),x=a.x+(next.x-a.x)/d*step,y=a.y+(next.y-a.y)/d*step;if(navClear(a.x,a.y,x,y,pad,allow)){a.dir=x>=a.x?1:-1;a.x=x;a.y=y;a.moving=true;}else{a._navRoute=null;}
  return distance;
}
function navConstrainClient(c,dt=1/60){const allow=c.id==='clown'?['trampoline']:c.id==='busker'?['stage']:c.id==='grandpa'?['bench']:[];if(c.id==='family'){if(!c._navMembers)c._navMembers=c.parts.map((p,i)=>navProjectPoint(p.x,p.y,i<2?5:3));for(let i=0;i<c.parts.length;i++){const p=c.parts[i],a=c._navMembers[i];navMove(a,p.x,p.y,i<2?60:125,dt,i<2?5:3);p.x=a.x;p.y=a.y;}}else Object.assign(c,navProjectPoint(c.x,c.y,5,allow));if(c.id==='couple'){const p=navProjectPoint(c.dx,c.dy,3);c.dx=p.x;c.dy=p.y;}}
function navResolvePlayer(pl,old){const safe=navProjectPoint(pl.x,pl.y,5);if(navClear(old.x,old.y,safe.x,safe.y,5)){pl.x=safe.x;pl.y=safe.y;return;}const candidates=[{x:pl.x,y:old.y},{x:old.x,y:pl.y}].filter(p=>navPointFree(p.x,p.y,5)&&navClear(old.x,old.y,p.x,p.y,5));if(candidates.length){candidates.sort((a,b)=>dist(b.x,b.y,old.x,old.y)-dist(a.x,a.y,old.x,old.y));Object.assign(pl,candidates[0]);return;}let lo=0,hi=1;for(let i=0;i<12;i++){const k=(lo+hi)/2;if(navClear(old.x,old.y,lerp(old.x,pl.x,k),lerp(old.y,pl.y,k),5))lo=k;else hi=k;}pl.x=lerp(old.x,pl.x,lo);pl.y=lerp(old.y,pl.y,lo);Object.assign(pl,navProjectPoint(pl.x,pl.y,5));}
